args.query:
\d api.application
\d api.app_user
\d reg.counterparty
select rolname from pg_roles where rolname !~ '^pg_';
select * from api.app_user;
select grantee,table_name,privilege_type from information_schema.role_table_grants where table_schema in ('api','reg');
select tablename,policyname,roles,cmd,qual,with_check from pg_policies;
select relname,relrowsecurity,relforcerowsecurity,relowner::regrole from pg_class where relnamespace in ('api'::regnamespace,'reg'::regnamespace) and relkind in ('r','v','f');
select tgname,tgrelid::regclass,pg_get_triggerdef(oid) from pg_trigger where not tgisinternal;

select * from api.status;
select p.proname,p.prosecdef,pg_get_functiondef(p.oid) from pg_proc p where pronamespace='priv'::regnamespace;
select a.number,s.name,a.company_inn,a.amount from api.application a join api.status s on s.id=a.status_id order by 1;
\d api.audit
select * from reg.counterparty;
select relname,reloptions from pg_class where relname='counterparty';

select r.rolname,m.rolname from pg_auth_members a join pg_roles r on r.oid=a.roleid join pg_roles m on m.oid=a.member;
select nspname,nspacl from pg_namespace where nspname in ('api','priv','reg');
select grantee,privilege_type from information_schema.role_routine_grants where specific_schema='priv' limit 20;

grant usage on schema api, priv to lawyer;
update api.app_user set role='lawyer' where login='lawyer1';

create table api.contract(
 id bigint generated always as identity primary key,
 number text not null unique,
 application_id integer not null references api.application(id),
 amount numeric not null check (amount>0),
 signed_on date not null default current_date,
 status text not null default 'Проект' check (status in ('Проект','Подписан'))
);
create or replace function priv.check_contract() returns trigger language plpgsql security definer set search_path to 'api' as $$
begin
 if not exists (select 1 from api.application a join api.status s on s.id=a.status_id where a.id=NEW.application_id and s.name='Одобрена') then
  raise exception 'договор можно заключить только по одобренной заявке' using errcode='check_violation';
 end if;
 return NEW;
end $$;
create trigger check_contract before insert or update on api.contract for each row execute function priv.check_contract();

alter table api.contract enable row level security;
grant select,insert,update on api.contract to lawyer;
grant all on api.contract to fund_admin;
grant select on api.contract to applicant;
create policy lawyer_all on api.contract for all to lawyer using (true) with check (true);
create policy admin_all on api.contract for all to fund_admin using (true) with check (true);
create policy applicant_read on api.contract for select to applicant using (
 exists (select 1 from api.application a where a.id=application_id and a.company_inn=priv.my_company()));

grant select on api.application to lawyer;
create policy lawyer_read on api.application for select to lawyer using (true);
grant select on api.status to lawyer;

create function priv.jwt_role() returns text language sql stable as $$ select current_setting('request.jwt.claims', true)::json ->> 'role' $$;
grant execute on function priv.jwt_role() to public;

create view api.company as
 select inn, legal_name, funding_limit from reg.counterparty
 where priv.jwt_role() in ('fund_admin','lawyer') or inn = priv.my_company();
grant select on api.company to fund_admin, lawyer, applicant;

create view api.limit_balance as
 select c.legal_name as company, c.funding_limit,
  ap.approved, coalesce(ct.contracted,0) as contracted,
  c.funding_limit - coalesce(ct.contracted,0) as remaining
 from reg.counterparty c
 join (select a.company_inn, sum(a.amount) approved from api.application a join api.status s on s.id=a.status_id and s.name='Одобрена' group by 1) ap on ap.company_inn=c.inn
 left join (select a.company_inn, sum(k.amount) contracted from api.contract k join api.application a on a.id=k.application_id group by 1) ct on ct.company_inn=c.inn
 where priv.jwt_role() in ('fund_admin','lawyer') or c.inn = priv.my_company();
grant select on api.limit_balance to fund_admin, lawyer, applicant;
notify pgrst,'reload schema';
